            // Weave the long schoolyard photo series through the wider album so adjacent cards keep a varied, nostalgic rhythm.
const memoryAlbumSeries = [
  memoryAlbumItems.filter(x => /^Kids_playing_at_school/i.test(x.file)),
  memoryAlbumItems.filter(x => /^Children_playing_in_a_field_/i.test(x.file))
];
const memoryAlbumMixed = [];
let albumCursor = 0;
while (memoryAlbumItems.length > memoryAlbumSeries.reduce((n, group) => n + group.length, 0) + albumCursor) {
  if (albumCursor < memoryAlbumItems.length - memoryAlbumSeries[0].length - memoryAlbumSeries[1].length) memoryAlbumMixed.push(memoryAlbumItems.filter(x => !/^Kids_playing_at_school|^Children_playing_in_a_field_/i.test(x.file))[albumCursor]);
  for (const group of memoryAlbumSeries) if (group[albumCursor]) memoryAlbumMixed.push(group[albumCursor]);
  albumCursor++;
}
// Add any singleton photos not consumed above if the source set has no series counterpart at that index.
const albumAlreadyMixed = new Set(memoryAlbumMixed.map(x => x.file));
for (const item of memoryAlbumItems) if (!albumAlreadyMixed.has(item.file)) memoryAlbumMixed.push(item);
memoryAlbumItems.splice(0, memoryAlbumItems.length, ...memoryAlbumMixed);
