    function openTableGame(){table=newTable();const bn=lang==='bn';document.querySelector('#tableIntro').textContent=bn?'প্যাডেল সরিয়ে বল ফেরান। প্রতিটি আঘাতে কোণ বদলান; ১১ পয়েন্টে দুই পয়েন্ট ব্যবধানে জিতুন।':'Move your paddle to return the ball. Your contact point changes the angle; first to 11, win by two.';document.querySelector('#tableDiffLabel').textContent=extraText().diff;document.querySelector('#tableHelp').textContent=bn?'A/D, ←/→, অথবা পর্দায় আঙুল/মাউস সরান। বলের দিকে প্যাডেল আনুন; কিনারায় লাগালে কোণ তীক্ষ্ণ হবে।':'Use A/D, arrows, touch, or mouse. Meet the ball with your paddle; edge hits create sharper angles.';document.querySelector('#tableOverTitle').textContent=bn?'সার্ভিস আপনার।':'Your serve.';document.querySelector('#tableOverText').textContent=bn?'বল নেমে আসার পথে প্যাডেল মিলিয়ে নিন।':'Track the ball down and meet it with your paddle.';document.querySelector('#tableStart').textContent=bn?'ম্যাচ শুরু':'Start match';document.querySelector('#tablePause').textContent=bn?'বিরতি':'Pause';document.querySelector('#tableAgain').textContent=bn?'আবার খেলুন':'Play again';document.querySelector('#tableClose').setAttribute('aria-label',bn?'বন্ধ করুন':'Close');document.querySelector('#tableOverlay').hidden=false;drawTable();tableScore();tableDialog.showModal()}
    function startTable(){table=newTable();drawTable();beginTableServe()}
    document.querySelector('#tableStart').addEventListener('click',()=>{if(table?.paused){table.paused=false;table.running=true;tableLast=0;document.querySelector('#tableOverlay').hidden=true;tableScore();tableFrame=requestAnimationFrame(tableLoop);return}if(table&&!table.over&&!table.running){beginTableServe();return}startTable()});document.querySelector('#tableAgain').addEventListener('click',startTable);document.querySelector('#tablePause').addEventListener('click',()=>{if(!table||table.over)return;if(table.paused){table.paused=false;table.running=true;tableLast=0;document.querySelector('#tableOverlay').hidden=true;tableFrame=requestAnimationFrame(tableLoop)}else{cancelAnimationFrame(tableFrame);table.paused=true;table.running=false;document.querySelector('#tableOverTitle').textContent=lang==='bn'?'একটু বিরতি':'Paused';document.querySelector('#tableOverText').textContent=lang==='bn'?'ম্যাচ থেমেছে। সার্ভিস ও স্কোর রাখা হয়েছে।':'Match paused. Score and serve are saved.';document.querySelector('#tableStart').textContent=lang==='bn'?'চালিয়ে যান':'Resume';document.querySelector('#tableOverlay').hidden=false;tableScore()}});document.querySelector('#tableClose').addEventListener('click',()=>{cancelAnimationFrame(tableFrame);table=null;tableDialog.close()});tableDialog.addEventListener('close',()=>{cancelAnimationFrame(tableFrame);tableKeys.clear()});
    tableEl.addEventListener('pointerdown',e=>{if(!table?.running)return;tableEl.setPointerCapture(e.pointerId);const r=tableEl.getBoundingClientRect();table.playerX=clamp((e.clientX-r.left)*640/r.width,100,540)});tableEl.addEventListener('pointermove',e=>{if(!table?.running)return;const r=tableEl.getBoundingClientRect();table.playerX=clamp((e.clientX-r.left)*640/r.width,100,540)});for(const[id,key,dir]of[['tableLeft','ArrowLeft',-1],['tableRight','ArrowRight',1]]){const b=document.querySelector('#'+id);let pressedAt=0;b.addEventListener('pointerdown',e=>{e.preventDefault();pressedAt=performance.now();tableKeys.add(key);b.setPointerCapture?.(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(n=>b.addEventListener(n,()=>{const held=performance.now()-pressedAt;tableKeys.delete(key);if(n==='pointerup'&&held<180&&table?.running)table.playerX=clamp(table.playerX+dir*48,100,540)}));b.addEventListener('click',e=>{if(e.detail===0&&table?.running)table.playerX=clamp(table.playerX+dir*48,100,540)})}document.addEventListener('keydown',e=>{if(tableDialog.open&&table?.running&&['ArrowLeft','ArrowRight','KeyA','KeyD'].includes(e.code)){tableKeys.add(e.code);e.preventDefault()}});document.addEventListener('keyup',e=>tableKeys.delete(e.code));
    document.querySelector('#carromDiff').addEventListener('change',()=>{if(carrom)carrom.difficulty=document.querySelector('#carromDiff').value});document.querySelector('#tableDiff').addEventListener('change',()=>{if(table)table.difficulty=document.querySelector('#tableDiff').value});
