    function resultCopy(kind){const words={bn:{meme:{win:"আজকের পুরস্কার: মোড়ের দোকানে এক কাপ চা—বাকি সবাই বলবে, “ভাগ্যটা তো আপনার দিকেই ছিল!” (চা অবশ্য নিজের পয়সায়।)",loss:"দর্শক বলছে—ভাই, আরেকবার খেলেন!",draw:"চায়ের দোকানে রিম্যাচ হবে নাকি?"},kicker:"খেলার ফল",title:{win:"আপনি জিতেছেন!",loss:"এবার জয় হলো না",draw:"ম্যাচ ড্র"},detail:{win:"দারুণ খেলেছেন—আরেক দফা খেলবেন?",loss:"খেলা এখানেই শেষ নয়—আবার চেষ্টা করুন।",draw:"দুজনের লড়াই জমেছিল—আবার খেলুন।"},stamp:{win:"জয়",loss:"আবার",draw:"ড্র"},again:"আবার খেলুন",continue:"ফল দেখি"},en:{meme:{win:"Your prize: one imaginary cup of tea from the corner shop. The shopkeeper says “lucky day!”—then asks you to pay.",loss:"The crowd says: one more round, boss!",draw:"Rematch at the tea stall?"},kicker:"The result",title:{win:"You won!",loss:"Not this time",draw:"A friendly draw"},detail:{win:"Well played. Ready for another round?",loss:"Every round is a fresh start. Try again?",draw:"A close match. Shall we play again?"},stamp:{win:"WIN",loss:"TRY",draw:"DRAW"},again:"Play again",continue:"See the score"}},c=words[lang];return{kicker:c.kicker,title:c.title[kind],detail:c.detail[kind],stamp:c.stamp[kind],again:c.again,continue:c.continue,meme:c.meme[kind]}}
