      const bn=lang==="bn",actor=s.players[p].name,token=i+1;
      let detail=old<0?(bn?actor+"-এর গুটি "+token+" ঘর থেকে নামল।":actor+" brought token "+token+" out of home."):next===57?(bn?actor+"-এর গুটি "+token+" ঘরে পৌঁছেছে।":actor+" brought token "+token+" home."):(bn?actor+"-এর গুটি "+token+" "+roll+" ঘর এগিয়েছে।":actor+" moved token "+token+" forward "+roll+" spaces.");
