    function bantumiSearch(s,depth){if(!s||s.done||depth<=0)return s?(s.cells[13]-s.cells[6])+(s.cells.slice(7,13).reduce((a,b)=>a+b,0)-s.cells.slice(0,6).reduce((a,b)=>a+b,0))*.12:0;const moves=bantumiMoves(s,s.turn);if(!moves.length)return s.cells[13]-s.cells[6];const scores=moves.map(i=>bantumiSearch(bantumiApply(s,s.turn,i),depth-1));return s.turn===1?Math.max(...scores):Math.min(...scores)}
    function renderBantumi(){const s=miniState,cells=s.sowing?s.displayCells:s.cells,me=lang==="bn"?"আপনি":"You",cpu=lang==="bn"?"কম্পিউটার":"Computer",status=s.sowing?(lang==="bn"?"একটি করে বীজ বোনা হচ্ছে…":"Sowing the seeds one by one…"):s.done?(s.winner===null?(lang==="bn"?"খেলা ড্র হয়েছে।":"The game is tied."):s.winner===0?(lang==="bn"?"আপনি জিতেছেন!":"You win!"):(lang==="bn"?"কম্পিউটার জিতেছে।":"Computer wins.")):s.turn===0?(lang==="bn"?"আপনার চাল—নিজের বীজভরা ঘর বেছে নিন।":"Your turn—choose a pit with seeds."):lang==="bn"?"কম্পিউটার চাল ভাবছে…":"Computer is choosing…",top=[12,11,10,9,8,7].map(i=>'<button class="bantumi-pit '+(s.lastSown===i?'seed-drop':'')+'" style="grid-row:1;grid-column:'+(14-i)+'" data-pit="'+i+'" disabled><small>'+(lang==="bn"?"ঘর ":"Pit ")+(i-6)+'</small><strong>'+cells[i]+'</strong></button>').join(""),bottom=[0,1,2,3,4,5].map(i=>'<button class="bantumi-pit '+(s.lastSown===i?'seed-drop':'')+'" style="grid-row:2;grid-column:'+(i+2)+'" data-pit="'+i+'" '+(s.sowing||s.turn!==0||!cells[i]||s.done?"disabled":"")+'><small>'+(lang==="bn"?"ঘর ":"Pit ")+(i+1)+'</small><strong>'+cells[i]+'</strong></button>').join("");playContent.innerHTML='<p class="play-instructions">'+(lang==="bn"?"প্রতি ঘরে চারটি বীজ দিয়ে শুরু। নিজের ঘর থেকে সব বীজ তুলে একে একে পরের ঘরে দিন; প্রতিপক্ষের দোকান বাদ দিন। শেষ বীজ নিজের দোকানে পড়লে আবার চাল, আর নিজের খালি ঘরে পড়ে উল্টো ঘরে বীজ থাকলে সেগুলো কাটুন। এক পাশ ফাঁকা হলে বেশি বীজ যার, তার জয়।":"Each pit starts with four seeds. Pick up every seed from one of your pits and sow them one by one, skipping the rival’s store. Land in your store for another turn; land in an empty pit on your side to capture seeds opposite. When one side empties, the larger store wins.")+'</p><p class="play-status" aria-live="polite">'+status+(s.last?" · "+s.last:"")+'</p><div class="bantumi-score"><span>'+me+' <strong>'+cells[6]+'</strong></span><span>'+cpu+' <strong>'+cells[13]+'</strong></span></div><div class="bantumi-board"><div class="bantumi-store">'+(lang==="bn"?"আপনার দোকান":"Your store")+'<strong>'+cells[6]+'</strong></div>'+top+'<div class="bantumi-store cpu">'+(lang==="bn"?"কম্পিউটারের দোকান":"Computer store")+'<strong>'+cells[13]+'</strong></div>'+bottom+'</div>'+restartButton(()=>startPlayable("bantumi"),lang==="bn"?"আবার খেলুন":"Play again");playContent.querySelectorAll("[data-pit]").forEach(b=>b.onclick=()=>bantumiPlay(0,Number(b.dataset.pit)));document.querySelector("#miniAgain").onclick=()=>startPlayable("bantumi");if(s.done)mountResultPopup(s.winner===0?"win":s.winner===1?"loss":"draw",()=>startPlayable("bantumi"));if(!s.done&&!s.sowing&&s.turn===1&&!s.cpuThinking){s.cpuThinking=true;const session=playSession;setTimeout(()=>{if(!playDialog.open||activePlay!=="bantumi"||session!==playSession||miniState!==s)return;const moves=bantumiMoves(s,1);if(!moves.length)return;let pick;if(gameDifficulty==="easy")pick=moves[Math.floor(Math.random()*moves.length)];else{const ranked=moves.map(i=>({i,value:bantumiSearch(bantumiApply(s,1,i),gameDifficulty==="hardest"?2:1)+Math.random()*(gameDifficulty==="hardest"?.02:.7)})).sort((a,b)=>b.value-a.value);pick=ranked[0].i}bantumiPlay(1,pick)},650)}}
