    function updateClassicRescue(s,dt){const p=s.player;if(s.tapDirection==="KeyA")p.x-=24;if(s.tapDirection==="KeyD")p.x+=24;if(s.tapDirection==="KeyW"&&p.y>=265)p.vy=-390;s.tapDirection="";if(classicKeys.has("KeyA"))p.x-=180*dt;if(classicKeys.has("KeyD"))p.x+=180*dt;p.x=Math.max(75,Math.min(270,p.x));if(classicKeys.has("KeyW")&&p.y>=265)p.vy=-390;p.y+=p.vy*dt;p.vy+=920*dt;if(p.y>265){p.y=265;p.vy=0}s.elapsed+=dt;s.scroll=(s.scroll+75*dt)%640;s.spawn+=dt;s.cooldown-=dt;s.hitWait=Math.max(0,s.hitWait-dt);const spawnRate=s.difficulty==="easy"?1.35:s.difficulty==="hardest"?.82:1.05;if(s.spawn>spawnRate&&s.score<12){s.spawn=0;s.enemies.push({x:620,y:265,hp:s.difficulty==="easy"?1:1+Math.floor(Math.random()*2),speed:s.difficulty==="easy"?72+Math.random()*22:s.difficulty==="hardest"?102+Math.random()*38:88+Math.random()*34,flash:0})}if((s.fireRequested||s.isFiring||classicKeys.has("KeyJ")||classicKeys.has("Space"))&&s.cooldown<=0){s.bullets.push({x:p.x+25,y:p.y-30});s.cooldown=.32;s.fireRequested=false}for(const b of s.bullets)b.x+=510*dt;for(const e of s.enemies){e.x-=e.speed*dt;e.flash=Math.max(0,e.flash-dt);if(Math.abs(e.x-p.x)<28&&Math.abs(e.y-p.y)<45&&s.hitWait<=0){s.lives--;s.hitWait=.7;p.flash=.3;document.dispatchEvent(new CustomEvent("agerdin:hit"));if(s.lives<=0){classicEnd("loss",lang==="bn"?"তিনটি জীবন শেষ। আরেকবার চেষ্টা করুন।":"All three lives are gone. Try another run.");return}}}for(const b of s.bullets){const hit=s.enemies.find(e=>e.hp>0&&Math.abs(e.x-b.x)<20&&Math.abs(e.y-b.y)<42);if(hit){hit.hp--;hit.flash=.15;b.x=700;if(hit.hp<=0)s.score++}}s.enemies=s.enemies.filter(e=>e.x>-40&&e.hp>0);s.bullets=s.bullets.filter(b=>b.x<680);if(s.score>=12)classicEnd("win",lang==="bn"?"১২টি লক্ষ্য পার হয়েছেন—পথ পরিষ্কার!":"You cleared all 12 targets. The route is open!");document.querySelector("#classicStatus").textContent=classicArcadeText[lang].rescueStatus+" · "+s.score+"/12 · "+classicArcadeText[lang].lives+" · "+s.lives}
    function aimGoalie(s){const cells=["0,0","1,0","2,0","0,1","1,1","2,1"],freq=new Map();s.history.forEach(x=>freq.set(x,(freq.get(x)||0)+1));const repeated=[...freq.entries()].sort((a,b)=>b[1]-a[1])[0];if(classicDifficulty==="easy")return cells[Math.floor(Math.random()*cells.length)];if(classicDifficulty==="hard"){if(repeated&&Math.random()<.58)return repeated[0];return cells[Math.floor(Math.random()*cells.length)]}if(repeated&&Math.random()<.84)return repeated[0];if(s.history.length>1){const last=s.history.at(-1);if(Math.random()<.55)return cells.find(x=>x!==last)}return cells[Math.floor(Math.random()*cells.length)]}
