    function updateClassicPenalty(s,dt){if(!s.shot){document.querySelector("#classicStatus").textContent=classicArcadeText[lang].shots+" · "+s.shots+"/5 · "+classicArcadeText[lang].goals+" · "+s.goals+" · "+classicArcadeText[lang].saves+" · "+s.saves;return}s.shot.time-=dt;if(s.shot.time<=0){if(s.shot.target===s.shot.keeper){s.saves++;document.querySelector("#classicStatus").textContent=classicArcadeText[lang].saved}else{s.goals++;document.querySelector("#classicStatus").textContent=classicArcadeText[lang].scored}s.shots++;s.shot=null;if(s.shots>=5){const result=s.goals>s.saves?"win":s.goals===s.saves?"draw":"loss";classicEnd(result,classicArcadeText[lang].goals+" "+s.goals+" — "+classicArcadeText[lang].saves+" "+s.saves)}}}
